 1→// Shared error logging helper for Edge Functions
 2→// Import: import { logSystemError } from "../_shared/logError.ts";
 3→
 4→import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
 5→
 6→interface ErrorLogEntry {
 7→  function_name: string;
 8→  error_type: string;
 9→  severity: "critical" | "warning" | "info";
10→  error_message: string;
11→  error_stack?: string;
12→  user_id?: string | null;
13→  job_id?: string | null;
14→  resume_id?: string | null;
15→  context_json?: Record<string, any>;
16→}
17→
18→export async function logSystemError(entry: ErrorLogEntry): Promise<void> {
19→  try {
20→    const supabase = createClient(
21→      Deno.env.get("SUPABASE_URL")!,
22→      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
23→    );
24→    await supabase.from("system_error_logs").insert({
25→      function_name: entry.function_name,
26→      error_type: entry.error_type,
27→      severity: entry.severity,
28→      error_message: entry.error_message.slice(0, 2000),
29→      error_stack: entry.error_stack?.slice(0, 4000) || null,
30→      user_id: entry.user_id || null,
31→      job_id: entry.job_id || null,
32→      resume_id: entry.resume_id || null,
33→      context_json: entry.context_json || {},
34→    });
35→  } catch {
36→    // Never throw from error logging — avoid infinite loops
37→    console.error("[logSystemError] Failed to write error log:", entry.error_message);
38→  }
39→}
40→
41→export function errorToMessage(err: unknown): string {
42→  if (err instanceof Error) return err.message;
43→  return String(err);
44→}
45→
46→export function errorToStack(err: unknown): string | undefined {
47→  if (err instanceof Error) return err.stack;
48→  return undefined;
49→}
